def prevent_row_split(row):
    tag=OxmlElement('w:cantSplit')
    row._tr.get_or_add_trPr().append(tag)

def set_repeat_table_header(row):
    trPr = row._tr.get_or_add_trPr(); el=OxmlElement('w:tblHeader'); el.set(qn('w:val'),'true');trPr.append(el)

def set_cell_border(cell):
    tcPr=cell._tc.get_or_add_tcPr(); borders=OxmlElement('w:tcBorders')
    for edge in ('top','left','bottom','right'):
        tag=OxmlElement('w:'+edge);tag.set(qn('w:val'),'single');tag.set(qn('w:sz'),'4');tag.set(qn('w:color'),'858585');borders.append(tag)
    tcPr.append(borders)

def shade(cell):
    e=OxmlElement('w:shd');e.set(qn('w:fill'),'E9E9E9');cell._tc.get_or_add_tcPr().append(e)

