def para(text='',align=None,indent=True,space_before=0):
    p=D.add_paragraph(style='Normal');p.add_run(text)
    if align is not None:p.alignment=align
    if not indent:p.paragraph_format.first_line_indent=Cm(0)
    if space_before:p.paragraph_format.space_before=Pt(space_before)
    return p


def rich(pieces,indent=True):
    p=D.add_paragraph(style='Normal')
    if not indent:p.paragraph_format.first_line_indent=Cm(0)
    for s,bold in pieces: r=p.add_run(s);r.bold=bold
    return p


def st(title,page_break=True):
    if title[0].isdigit():
        p=D.add_paragraph(title,style='Heading 1')
    else:
        p=D.add_paragraph(title.upper(),style='Structural')
    if page_break:p.paragraph_format.page_break_before=True
    return p


def heading(num,title):
    p=D.add_paragraph(f'{num} {title}',style='Heading 1');return p


def sub(num,title):
    p=D.add_paragraph(f'{num} {title}',style='Heading 2')
    if num=='4.3':p.paragraph_format.page_break_before=True
    return p


def table(headers,rows,widths=None):
    t=D.add_table(rows=1,cols=len(headers));t.style='Table Grid';t.alignment=WD_TABLE_ALIGNMENT.CENTER
    for j,val in enumerate(headers):
        cell=t.rows[0].cells[j];cell.text=str(val);shade(cell)
        for q in cell.paragraphs:
            q.paragraph_format.first_line_indent=Cm(0);q.paragraph_format.line_spacing=1.0
            for r in q.runs:r.bold=True;r.font.size=Pt(10.5)
        set_cell_border(cell)
    set_repeat_table_header(t.rows[0])
    for row in rows:
        cells=t.add_row().cells
        for j,v in enumerate(row):
            cells[j].text=str(v);cells[j].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            for pp in cells[j].paragraphs:
                pp.paragraph_format.first_line_indent=Cm(0)
                pp.paragraph_format.line_spacing=1.0
                pp.paragraph_format.space_after=Pt(0)
                for r in pp.runs:r.font.size=Pt(10.5)
            set_cell_border(cells[j])
    for row in t.rows:prevent_row_split(row)
    if widths:
        t.autofit=False
        for j,col in enumerate(t.columns):col.width=Cm(widths[j])
        for row in t.rows:
            for j,cell in enumerate(row.cells):cell.width=Cm(widths[j])
    D.add_paragraph().paragraph_format.space_after=Pt(0)
    return t


def cap(text):
    p=D.add_paragraph(text)
    if text.startswith(('Таблица 4 —','Таблица 6 —')):p.paragraph_format.page_break_before=True
    p.paragraph_format.keep_with_next=True
    p.alignment=WD_ALIGN_PARAGRAPH.CENTER;p.paragraph_format.first_line_indent=Cm(0);p.paragraph_format.space_before=Pt(6);p.paragraph_format.space_after=Pt(8)
    return p


def code_lines(lines):
    for text in lines.splitlines():
        p=D.add_paragraph();p.paragraph_format.first_line_indent=Cm(0)
        p.paragraph_format.line_spacing=1;p.paragraph_format.space_after=Pt(0)
        r=p.add_run(text or ' ');r.font.name='Liberation Mono';r.font.size=Pt(9)

